// Temporary config: project .eslintrc.cjs minus the broken local
// `duplicate-attributes` plugin (its `file:eslint-rules` package dir is
// missing in this checkout, so it cannot load). Used only for a local
// lint pass of the changed file; not committed.
const path = require('path')
const base = require(path.resolve(__dirname, '.eslintrc.cjs'))
const prefix = 'duplicate-attributes/'
base.plugins = (base.plugins || []).filter((p) => p !== 'duplicate-attributes')
if (base.rules) {
  for (const k of Object.keys(base.rules)) {
    if (k.startsWith(prefix)) delete base.rules[k]
  }
}
if (base.overrides) {
  for (const o of base.overrides) {
    if (o.rules) {
      for (const k of Object.keys(o.rules)) {
        if (k.startsWith(prefix)) delete o.rules[k]
      }
    }
  }
}
module.exports = base
